const P = {"tool": "Software Supply Chain Attestation System", "steps": ["fetch-deps", "build-82", "test", "sign", "publish"]};

function demoMain(P){
  function fnv(s){ var h=0x811c9dc5; for(var i=0;i<s.length;i++){ h^=s.charCodeAt(i); h=Math.imul(h,0x01000193)>>>0; } return ('0000000'+h.toString(16)).slice(-8); }
  var h='GENESIS', i;
  for(i=0;i<P.steps.length;i++) h=fnv(h+'|'+P.steps[i]);
  return 'Supply-chain attestation ('+P.tool+'): '+P.steps.length+' build steps hash-chained, head='+h+', chain length OK='+(h.length===8);
}
console.log(demoMain(P));

